#include <map>
#include <string>

int main() {
    std::map<int, std::string> m = {{10, "A"}};
    auto it = m.begin();

    // Correct: Modify the mapped value (T)
    it->second = "New Value";

    // Error: Cannot modify the key (const Key)
    // it->first = 20; // ERROR: assignment of read-only member

    // Correct way to change the key:
    std::string value = it->second;
    m.erase(it);
    m.insert({20, value});
}
